require_once 'includes/auth.php'; wajib_login(['admin','petugas']); $namaHalaman='Pengembalian Alat';$pesan='';
if(isset($_POST['kembalikan'])){$id=(int)($_POST['id_peminjaman']??0);$tgl=$_POST['tanggal_kembali']??date('Y-m-d');$s=mysqli_prepare($koneksi,"SELECT status,tanggal_pinjam FROM peminjaman WHERE id_peminjaman=?");mysqli_stmt_bind_param($s,'i',$id);mysqli_stmt_execute($s);$p=mysqli_fetch_assoc(mysqli_stmt_get_result($s));mysqli_stmt_close($s);if(!$p)$pesan='Data peminjaman tidak ditemukan.';elseif($p['status']!=='Dipinjam')$pesan='Peminjaman ini sudah dikembalikan.';elseif($tgl<$p['tanggal_pinjam'])$pesan='Tanggal kembali tidak boleh sebelum tanggal pinjam.';else{$s=mysqli_prepare($koneksi,"UPDATE peminjaman SET status='Dikembalikan',tanggal_kembali=? WHERE id_peminjaman=?");mysqli_stmt_bind_param($s,'si',$tgl,$id);if(mysqli_stmt_execute($s)){catat_aktivitas($koneksi,(int)$_SESSION['id_user'],'Memproses pengembalian alat');header('Location: pengembalian.php?ok=1');exit;}else $pesan='Gagal memproses pengembalian.';mysqli_stmt_close($s);}}
$q=mysqli_query($koneksi,"SELECT p.id_peminjaman,p.tanggal_pinjam,p.tanggal_kembali,p.jumlah,p.status,u.nama,a.nama_alat FROM peminjaman p JOIN user u ON u.id_user=p.id_user JOIN alat a ON a.id_alat=p.id_alat ORDER BY p.id_peminjaman DESC");
require 'includes/header.php'; ?><h2>Pengembalian Alat</h2><?php if($pesan): ?><div class="alert alert-warning"><?= e($pesan) ?></div><?php endif; ?><?php if(isset($_GET['ok'])): ?><div class="alert alert-success">Pengembalian berhasil diproses.</div><?php endif; ?>
<div class="panel table-responsive"><table class="table align-middle"><thead><tr><th>Peminjam</th><th>Alat</th><th>Tgl Pinjam</th><th>Jumlah</th><th>Status</th><th>Proses Pengembalian</th></tr></thead><tbody><?php while($p=mysqli_fetch_assoc($q)): ?><tr><td><?= e($p['nama']) ?></td><td><?= e($p['nama_alat']) ?></td><td><?= e($p['tanggal_pinjam']) ?></td><td><?= (int)$p['jumlah'] ?></td><td><?= e($p['status']) ?></td><td><?php if($p['status']==='Dipinjam'): ?><form method="post" class="d-flex gap-2"><input type="hidden" name="id_peminjaman" value="<?= (int)$p['id_peminjaman'] ?>"><input type="date" name="tanggal_kembali" class="form-control form-control-sm" value="<?= date('Y-m-d') ?>" required><button class="btn btn-sm btn-primary" name="kembalikan">Kembalikan</button></form><?php else: ?>Dikembalikan: <?= e($p['tanggal_kembali']) ?><?php endif; ?></td></tr><?php endwhile; ?></tbody></table></div><?php require 'includes/footer.php'; ?>
